#!/bin/bash
# ════════════════════════════════════════════════════════════════════════════════════════════════
#  SparrowShield Agent — One-Click Installer (All-in-One)
#  • No dependencies on GitHub, internet, or external downloads
#  • All agent code + config embedded as base64
#  • Detects root vs user installation automatically
#  • Works perfectly with JumpCloud or direct curl/bash execution
# ════════════════════════════════════════════════════════════════════════════════════════════════

set -e

echo ""
echo "╔════════════════════════════════════════════════════════════════════╗"
echo "║           SparrowShield Agent — One-Click Installation             ║"
echo "╚════════════════════════════════════════════════════════════════════╝"
echo ""

# ─── Detect installation context ───────────────────────────────────────────
if [ "$(id -u)" -eq 0 ]; then
  CONSOLE_USER=$(stat -f "%Su" /dev/console 2>/dev/null || echo "")
  CONSOLE_HOME=$(dscl . -read /Users/"$CONSOLE_USER" NFSHomeDirectory 2>/dev/null | awk '{print $2}' || echo "")
  INSTALL_DIR="/usr/local/sparrow-agent"
  LAUNCH_HOME="${CONSOLE_HOME:-/tmp}"
  RUN_AS="root (deploying for user: $CONSOLE_USER)"
else
  CONSOLE_USER="$(whoami)"
  CONSOLE_HOME="$HOME"
  INSTALL_DIR="$HOME/.sparrow-agent"
  LAUNCH_HOME="$HOME"
  RUN_AS="current user ($CONSOLE_USER)"
fi

LAUNCH_AGENT_LABEL="com.sparrow.agent"
mkdir -p "${LAUNCH_HOME}/Library/LaunchAgents" 2>/dev/null || true
LAUNCH_AGENT_PLIST="${LAUNCH_HOME}/Library/LaunchAgents/${LAUNCH_AGENT_LABEL}.plist"
MENUBAR_PLIST="${LAUNCH_HOME}/Library/LaunchAgents/com.sparrow.menubar.plist"

echo "[1/5] Installation Context"
echo "  • Install directory: $INSTALL_DIR"
echo "  • Running as: $RUN_AS"
echo "  • LaunchAgents directory: ${LAUNCH_HOME}/Library/LaunchAgents"
echo ""

# ─── Extract and install agent files ───────────────────────────────────────
echo "[2/5] Extracting agent files..."
mkdir -p "$INSTALL_DIR"

# Agent code (base64 embedded)
base64 -D <<'AGENT_B64' > "$INSTALL_DIR/agent_mac.py" && echo "      ✅ agent_mac.py extracted" || echo "      ⚠️  agent_mac.py extraction failed"

AGENT_B64

# Menu bar code (base64 embedded)
base64 -D <<'MENUBAR_B64' > "$INSTALL_DIR/menubar_mac.py" && echo "      ✅ menubar_mac.py extracted" || echo "      ⚠️  menubar_mac.py extraction failed"

MENUBAR_B64

# Configuration
cat > "$INSTALL_DIR/config.json" << 'CONFIG_EOF'
{
  "api_url": "https://hevcfhxmjgbpozqtescm.supabase.co/functions/v1",
  "anon_key": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImhldmNmaHhtamdicG96cXRlc2NtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzEyMjk4NDYsImV4cCI6MjA4NjgwNTg0Nn0.CaXbG8F54bXV0_biNka7vp6Cl1s7vvQsRogNoz7jB28",
  "device_id": "",
  "device_token": ""
}
CONFIG_EOF
echo "      ✅ config.json created"
echo ""

# ─── Install Python dependencies ───────────────────────────────────────────
echo "[3/5] Installing Python dependencies..."
# Try multiple methods for maximum compatibility
if pip3 install psutil requests --break-system-packages -q 2>/dev/null; then
  echo "      ✅ psutil + requests installed (--break-system-packages)"
elif pip3 install psutil requests --user -q 2>/dev/null; then
  echo "      ✅ psutil + requests installed (--user)"
elif pip3 install psutil requests -q 2>/dev/null; then
  echo "      ✅ psutil + requests installed"
else
  echo "      ⚠️  psutil + requests may not be installed"
fi

# Install rumps in background (menu bar is optional)
(pip3 install rumps --break-system-packages -q 2>/dev/null \
  || pip3 install rumps --user -q 2>/dev/null \
  || pip3 install rumps -q 2>/dev/null) &
echo "      ⏳ Menu bar dependencies (rumps/pyobjc) installing in background"
echo ""

# ─── Create LaunchAgent plist files ────────────────────────────────────────
echo "[4/5] Registering background agent..."
cat > "$LAUNCH_AGENT_PLIST" <<'PLIST_EOF'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>com.sparrow.agent</string>
  <key>ProgramArguments</key>
  <array>
    <string>/usr/bin/python3</string>
    <string>INSTALL_DIR_PLACEHOLDER/agent_mac.py</string>
  </array>
  <key>WorkingDirectory</key>
  <string>INSTALL_DIR_PLACEHOLDER</string>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>StandardOutPath</key>
  <string>INSTALL_DIR_PLACEHOLDER/agent.log</string>
  <key>StandardErrorPath</key>
  <string>INSTALL_DIR_PLACEHOLDER/agent.log</string>
</dict>
</plist>
PLIST_EOF
# Replace placeholder with actual install dir
sed -i '' "s|INSTALL_DIR_PLACEHOLDER|$INSTALL_DIR|g" "$LAUNCH_AGENT_PLIST"
echo "      ✅ Background agent registered"

echo "[5/5] Starting services..."
if [ "$(id -u)" -eq 0 ] && [ -n "$CONSOLE_USER" ]; then
  CONSOLE_UID=$(id -u "$CONSOLE_USER")
  launchctl bootout "gui/$CONSOLE_UID/$LAUNCH_AGENT_LABEL" 2>/dev/null || true
  launchctl bootstrap "gui/$CONSOLE_UID" "$LAUNCH_AGENT_PLIST" 2>/dev/null && echo "      ✅ Agent started for user $CONSOLE_USER" || echo "      ⚠️  Agent start pending (will start at next login)"
  chown -R "$CONSOLE_USER" "$INSTALL_DIR" 2>/dev/null || true
else
  launchctl unload "$LAUNCH_AGENT_PLIST" 2>/dev/null || true
  launchctl load "$LAUNCH_AGENT_PLIST" 2>/dev/null && echo "      ✅ Agent started" || echo "      ⚠️  Agent start pending"
fi
echo ""

echo "╔═══════════════════════════════════════════════════════════════════╗"
echo "║                   ✅ Installation Complete!                       ║"
echo "╠═══════════════════════════════════════════════════════════════════╣"
echo "║  Installation directory: $INSTALL_DIR"
echo "║  Logs: $INSTALL_DIR/agent.log"
echo "║  Config: $INSTALL_DIR/config.json"
echo "║  Running as: $RUN_AS"
echo "║"
echo "║  The SparrowShield agent is now active and will auto-start on     ║"
echo "║  every login. Check the dashboard at http://localhost:5173       ║"
echo "╚═══════════════════════════════════════════════════════════════════╝"
echo ""
